#include <iostream>
#include <iomanip>

class SavingsAccount {
public:
    explicit SavingsAccount(double balance) : savingsBalance(balance >= 0.0 ? balance : 0.0) {}

    void calculateMonthlyInterest() {
        savingsBalance += savingsBalance * (annualInterestRate / 12.0);
    }

    double getBalance() const { return savingsBalance; }

    static void modifyInterestRate(double newRate) {
        if (newRate >= 0.0) {
            annualInterestRate = newRate;
        }
    }

    static double getInterestRate() {
        return annualInterestRate;
    }

private:
    double savingsBalance{0.0};
    // C++17 inline static data member
    inline static double annualInterestRate{0.03};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    SavingsAccount saver1(2000.00);
    SavingsAccount saver2(3000.00);

    SavingsAccount::modifyInterestRate(0.03);
    saver1.calculateMonthlyInterest();
    saver2.calculateMonthlyInterest();

    std::cout << "Month 1 (Rate: 3%):\n";
    std::cout << "Saver1: $" << saver1.getBalance() << "\n";
    std::cout << "Saver2: $" << saver2.getBalance() << "\n";

    SavingsAccount::modifyInterestRate(0.04);
    saver1.calculateMonthlyInterest();
    saver2.calculateMonthlyInterest();

    std::cout << "Month 2 (Rate: 4%):\n";
    std::cout << "Saver1: $" << saver1.getBalance() << "\n";
    std::cout << "Saver2: $" << saver2.getBalance() << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

class Time24 {
public:
    // Single constructor with default values prevents ambiguous default constructor calls
    explicit Time24(int h = 0, int m = 0, int s = 0) {
        setTime(h, m, s);
    }

    void setTime(int h, int m, int s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            totalSeconds = h * 3600 + m * 60 + s;
        } else {
            totalSeconds = 0; // Default fallback
        }
    }

    // Implementation hiding: Hour, minute, second calculated on the fly
    int getHour() const { return totalSeconds / 3600; }
    int getMinute() const { return (totalSeconds % 3600) / 60; }
    int getSecond() const { return totalSeconds % 60; }

    void tick() {
        totalSeconds = (totalSeconds + 1) % 86400;
    }

    void printUniversal() const {
        std::cout << std::setfill('0') 
                  << std::setw(2) << getHour() << ":"
                  << std::setw(2) << getMinute() << ":"
                  << std::setw(2) << getSecond() << "\n";
    }

private:
    // Internal representation: Seconds since midnight (Exercise 17.22)
    int totalSeconds{0};
};

int main() {
    Time24 t1; // Invokes Time24(0, 0, 0)
    Time24 t2(23, 59, 59);

    std::cout << "Initial t1: ";
    t1.printUniversal();

    std::cout << "Initial t2: ";
    t2.printUniversal();

    t2.tick();
    std::cout << "t2 after tick: ";
    t2.printUniversal();

    return 0;
}
